8	 *
9	 * <p>The level starts at 1, gains 1 when an email is present and gains 1 when the owner's
10	 * {@code namesakeCount} is 0 (the name was unique on create). These pre-tenure factors are held at or
11	 * below {@link #PRE_TENURE_MAX} (3) by a guard, so email presence and a unique name carry an owner no
12	 * higher than level 3 on their own. Level 4 is reserved for tenure and is awarded only once an owner
13	 * has been registered for more than {@link #TENURE_DAYS_FOR_MAX} (365) days; a newly created owner has
14	 * zero tenure, so it never exceeds level 3.
15	 *
16	 * <p>This replaces the former string membership tier and is the single source of truth for the
17	 * computation shared by {@code OwnerMapper} (the {@code membershipLevel} response field) and the
18	 * create audit line.
19	 */
20	public final class MembershipLevel {
21	
22	    /** The highest level this rule awards. */
23	    public static final int MAX = 4;
24	
25	    /** Guard ceiling for the pre-tenure factors (email, unique name) before the tenure bump. */
26	    public static final int PRE_TENURE_MAX = 3;
27	
28	    /** An owner must have been registered for more than this many days to be eligible for level 4. */
29	    public static final long TENURE_DAYS_FOR_MAX = 365;
30	
31	    private MembershipLevel() {
32	    }
33	
34	    /**
35	     * Compute the membership level for an owner.
36	     *
37	     * @param owner the owner; its {@code email}, {@code namesakeCount} and tenure drive the result
38	     * @return the level, between 1 and {@link #MAX} inclusive
39	     */
40	    public static int of(Owner owner) {
41	        int level = 1;
42	        if (owner.hasEmail()) {
43	            level++;
44	        }
45	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
46	            level++;
47	        }
48	        level = Math.min(level, PRE_TENURE_MAX); // guard: pre-tenure factors cannot reach level 4
49	        if (tenureDays(owner) > TENURE_DAYS_FOR_MAX) {
50	            level++;
51	        }
52	        return Math.min(level, MAX);
53	    }
54	
55	    /**
56	     * Days elapsed since the owner's registration date, or 0 when it is unknown (e.g. a brand-new
57	     * owner being created). Never negative for a future registration date.
58	     */
59	    private static long tenureDays(Owner owner) {
60	        LocalDate registrationDate = owner.getRegistrationDate();
61	        if (registrationDate == null) {
62	            return 0;
63	        }
64	        long days = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
65	        return Math.max(days, 0);
